from itertools import combinations
G=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0],[0]*7,[0]*7,[0]*7]
S={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x==8}
tiles=[]
for r in range(6):
 for c in range(6):
  box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if box<=S: tiles.append(('sq',box))
  for miss in box:
   t=box-{miss}
   if t<=S: tiles.append(('L'+str(miss),t))

def search(rem, used=[]):
 if not rem: return [used]
 x=min(rem,key=lambda p:sum(t<=rem for _,t in tiles if p in t))
 sols=[]
 for kind,t in tiles:
  if x in t and t<=rem: sols+=search(rem-t,used+[(kind,t)])
 return sols
sols=search(S)
print(len(S),len(sols))
