source='''def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    tiles = []
    height, width = len(grid), len(grid[0])
    for r in range(height - 1):
        for c in range(width - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= cells:
                tiles.append((box, 1))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)]:
                piece = box - {missing}
                if piece <= cells:
                    tiles.append((piece, color))

    def cover(remaining, chosen):
        if not remaining:
            return chosen
        options = [(piece, color) for piece, color in tiles if piece <= remaining]
        cell = min(remaining, key=lambda p: sum(p in piece for piece, _ in options))
        for piece, color in options:
            if cell in piece:
                result = cover(remaining - piece, chosen + [(piece, color)])
                if result is not None:
                    return result
        return None

    result = cover(cells, [])
    output = [[0 for _ in row] for row in grid]
    if result is None:
        return output
    for piece, color in result:
        for r, c in piece:
            output[r][c] = color
    return output
